WITH filtered AS (SELECT id, account_id, txn_type, amount, txn_time, merchant, is_flagged, SUBSTRING(merchant, 1, 2) AS merchant_prefix, LENGTH(txn_type) AS txn_type_length FROM transactions WHERE txn_time >= DATE '2023-08-13'), flagged AS (SELECT *, CASE WHEN txn_time - LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) > INTERVAL 30 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM filtered), sessions_transactions AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM flagged) SELECT DATE_TRUNC('YEAR', txn_time) AS year_start, SUM(txn_type_length) FILTER (WHERE merchant = 'Amazon') AS amazon_total_txn_type_length, MIN(amount) AS min_amount, MAX(txn_time) AS last_txn_time FROM sessions_transactions GROUP BY DATE_TRUNC('YEAR', txn_time) ORDER BY min_amount DESC NULLS LAST;
